-- PostgreSQL 14+; run against the existing relief360 database.
CREATE TABLE IF NOT EXISTS USER_ACCOUNT(user_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','ngo','medical','volunteer')),phone TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Inactive')));
CREATE TABLE IF NOT EXISTS DISASTER(disaster_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,disaster_type TEXT NOT NULL,disaster_name TEXT NOT NULL,location TEXT NOT NULL,severity TEXT NOT NULL CHECK(severity IN ('Critical','High','Moderate','Low')),start_date DATE NOT NULL,status TEXT NOT NULL DEFAULT 'Active',description TEXT NOT NULL DEFAULT '',latitude REAL,longitude REAL,CHECK(latitude BETWEEN -90 AND 90),CHECK(longitude BETWEEN -180 AND 180));
CREATE TABLE IF NOT EXISTS CAMP(camp_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,disaster_id INTEGER NOT NULL REFERENCES DISASTER,camp_name TEXT NOT NULL,location TEXT NOT NULL,capacity INTEGER NOT NULL CHECK(capacity>0),contact_phone TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'Open' CHECK(status IN ('Open','Closed')),latitude REAL,longitude REAL,UNIQUE(disaster_id,camp_name),CHECK(latitude BETWEEN -90 AND 90),CHECK(longitude BETWEEN -180 AND 180));
CREATE TABLE IF NOT EXISTS VICTIM(victim_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,disaster_id INTEGER NOT NULL REFERENCES DISASTER,full_name TEXT NOT NULL,gender TEXT NOT NULL,date_of_birth DATE,phone TEXT NOT NULL DEFAULT '',address TEXT NOT NULL DEFAULT '',medical_notes TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'Registered',registered_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS VICTIM_CAMP_ASSIGNMENT(assignment_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,victim_id INTEGER NOT NULL REFERENCES VICTIM,camp_id INTEGER NOT NULL REFERENCES CAMP,assigned_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,released_at TIMESTAMPTZ,status TEXT NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Released')),CHECK((status='Active' AND released_at IS NULL) OR (status='Released' AND released_at IS NOT NULL)),CHECK(released_at IS NULL OR released_at>=assigned_at));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_stay ON VICTIM_CAMP_ASSIGNMENT(victim_id) WHERE status='Active';
CREATE TABLE IF NOT EXISTS MISSING_REPORT(report_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,disaster_id INTEGER NOT NULL REFERENCES DISASTER,matched_victim_id INTEGER REFERENCES VICTIM,missing_name TEXT NOT NULL,age INTEGER CHECK(age BETWEEN 0 AND 130),gender TEXT NOT NULL,identifying_marks TEXT NOT NULL DEFAULT '',last_seen_location TEXT NOT NULL,last_seen_date DATE NOT NULL,reporter_name TEXT NOT NULL,reporter_phone TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Searching' CHECK(status IN ('Searching','Found','Family Reunited')),reported_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(status='Searching' OR matched_victim_id IS NOT NULL));
CREATE TABLE IF NOT EXISTS VOLUNTEER(volunteer_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id INTEGER UNIQUE REFERENCES USER_ACCOUNT,full_name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT NOT NULL DEFAULT '',primary_skill TEXT NOT NULL,availability TEXT NOT NULL DEFAULT 'Available',status TEXT NOT NULL DEFAULT 'Active');
CREATE TABLE IF NOT EXISTS VOLUNTEER_ASSIGNMENT(assignment_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,volunteer_id INTEGER NOT NULL REFERENCES VOLUNTEER,disaster_id INTEGER NOT NULL REFERENCES DISASTER,task_description TEXT NOT NULL,assigned_date TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,shift TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Completed')));
CREATE TABLE IF NOT EXISTS VOLUNTEER_CAMP_ASSIGNMENT(assignment_id INTEGER PRIMARY KEY REFERENCES VOLUNTEER_ASSIGNMENT,camp_id INTEGER NOT NULL REFERENCES CAMP);
CREATE TABLE IF NOT EXISTS DONOR(donor_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,donor_name TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '',email TEXT NOT NULL DEFAULT '',address TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS DONATION(donation_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,donor_id INTEGER NOT NULL REFERENCES DONOR,disaster_id INTEGER NOT NULL REFERENCES DISASTER,amount BIGINT NOT NULL CHECK(amount>0),donation_date DATE NOT NULL,payment_mode TEXT NOT NULL,transaction_ref TEXT NOT NULL DEFAULT '',receipt_no TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS INVENTORY_ITEM(item_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,item_name TEXT NOT NULL,category TEXT NOT NULL,unit TEXT NOT NULL,reorder_level INTEGER NOT NULL DEFAULT 0 CHECK(reorder_level>=0),UNIQUE(item_name,unit));
CREATE TABLE IF NOT EXISTS CAMP_INVENTORY(camp_id INTEGER NOT NULL REFERENCES CAMP,item_id INTEGER NOT NULL REFERENCES INVENTORY_ITEM,quantity_on_hand BIGINT NOT NULL CHECK(quantity_on_hand>=0),last_updated TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(camp_id,item_id));
CREATE TABLE IF NOT EXISTS DISTRIBUTION(distribution_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,disaster_id INTEGER NOT NULL REFERENCES DISASTER,distributed_by INTEGER REFERENCES VOLUNTEER,distribution_date TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS DISTRIBUTION_SOURCE(distribution_id INTEGER PRIMARY KEY REFERENCES DISTRIBUTION,camp_id INTEGER NOT NULL REFERENCES CAMP);
CREATE TABLE IF NOT EXISTS CAMP_DISTRIBUTION(distribution_id INTEGER PRIMARY KEY REFERENCES DISTRIBUTION,camp_id INTEGER NOT NULL REFERENCES CAMP);
CREATE TABLE IF NOT EXISTS VICTIM_DISTRIBUTION(distribution_id INTEGER PRIMARY KEY REFERENCES DISTRIBUTION,victim_id INTEGER NOT NULL REFERENCES VICTIM);
CREATE TABLE IF NOT EXISTS DISTRIBUTION_ITEM(distribution_id INTEGER NOT NULL REFERENCES DISTRIBUTION,item_id INTEGER NOT NULL REFERENCES INVENTORY_ITEM,quantity BIGINT NOT NULL CHECK(quantity>0),PRIMARY KEY(distribution_id,item_id));
CREATE TABLE IF NOT EXISTS MEDICAL_CASE(case_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,victim_id INTEGER NOT NULL REFERENCES VICTIM,assigned_medical_user_id INTEGER REFERENCES USER_ACCOUNT,request_date TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,condition_summary TEXT NOT NULL,priority TEXT NOT NULL CHECK(priority IN ('Critical','High','Moderate','Low')),treatment_details TEXT NOT NULL DEFAULT '',treatment_date TIMESTAMPTZ,status TEXT NOT NULL DEFAULT 'Open' CHECK(status IN ('Open','Under Treatment','Closed')));
CREATE TABLE IF NOT EXISTS VEHICLE(vehicle_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,vehicle_no TEXT NOT NULL UNIQUE,vehicle_type TEXT NOT NULL,capacity INTEGER NOT NULL CHECK(capacity>0),driver_name TEXT NOT NULL,driver_phone TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Available' CHECK(status IN ('Available','Maintenance')),fuel_percentage INTEGER NOT NULL DEFAULT 100 CHECK(fuel_percentage BETWEEN 0 AND 100));
CREATE TABLE IF NOT EXISTS VEHICLE_ALLOCATION(allocation_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,vehicle_id INTEGER NOT NULL REFERENCES VEHICLE,disaster_id INTEGER NOT NULL REFERENCES DISASTER,purpose TEXT NOT NULL,from_location TEXT NOT NULL,to_location TEXT NOT NULL,assigned_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,returned_at TIMESTAMPTZ,status TEXT NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Returned')),CHECK((status='Active' AND returned_at IS NULL) OR (status='Returned' AND returned_at IS NOT NULL)),CHECK(returned_at IS NULL OR returned_at>=assigned_at));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_vehicle ON VEHICLE_ALLOCATION(vehicle_id) WHERE status='Active';
CREATE TABLE IF NOT EXISTS VEHICLE_CAMP_ALLOCATION(allocation_id INTEGER PRIMARY KEY REFERENCES VEHICLE_ALLOCATION,camp_id INTEGER NOT NULL REFERENCES CAMP);
CREATE TABLE IF NOT EXISTS ALERT(alert_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,disaster_id INTEGER NOT NULL REFERENCES DISASTER,created_by INTEGER NOT NULL REFERENCES USER_ACCOUNT,alert_type TEXT NOT NULL,severity TEXT NOT NULL CHECK(severity IN ('Critical','High','Moderate','Low')),message TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,status TEXT NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Resolved')));
CREATE TABLE IF NOT EXISTS CAMP_ALERT(alert_id INTEGER PRIMARY KEY REFERENCES ALERT,camp_id INTEGER NOT NULL REFERENCES CAMP);
CREATE OR REPLACE VIEW camp_occupancy AS SELECT c.*,COUNT(a.assignment_id) occupancy,ROUND(100.0*COUNT(a.assignment_id)/c.capacity,2) occupancy_percent FROM CAMP c LEFT JOIN VICTIM_CAMP_ASSIGNMENT a ON a.camp_id=c.camp_id AND a.status='Active' GROUP BY c.camp_id;
CREATE OR REPLACE VIEW stock_report AS SELECT ci.*,i.item_name,i.category,i.unit,i.reorder_level,c.camp_name,c.disaster_id,(ci.quantity_on_hand<=i.reorder_level) low_stock FROM CAMP_INVENTORY ci JOIN INVENTORY_ITEM i USING(item_id) JOIN CAMP c USING(camp_id);
CREATE INDEX IF NOT EXISTS idx_camp_disaster ON CAMP(disaster_id);
CREATE INDEX IF NOT EXISTS idx_victim_disaster ON VICTIM(disaster_id);
CREATE INDEX IF NOT EXISTS idx_missing_disaster ON MISSING_REPORT(disaster_id);
CREATE INDEX IF NOT EXISTS idx_assignment_disaster ON VOLUNTEER_ASSIGNMENT(disaster_id);
CREATE INDEX IF NOT EXISTS idx_donation_disaster ON DONATION(disaster_id);
CREATE INDEX IF NOT EXISTS idx_distribution_disaster ON DISTRIBUTION(disaster_id);
CREATE INDEX IF NOT EXISTS idx_alert_disaster ON ALERT(disaster_id);
CREATE INDEX IF NOT EXISTS idx_stay_camp ON VICTIM_CAMP_ASSIGNMENT(camp_id);
CREATE INDEX IF NOT EXISTS idx_medical_victim ON MEDICAL_CASE(victim_id);

CREATE UNIQUE INDEX IF NOT EXISTS user_email_case_insensitive ON USER_ACCOUNT(lower(email));

-- Semantic constraints apply to writes from both the webpage and pgAdmin.
CREATE OR REPLACE FUNCTION relief360_relationship_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE parent_disaster integer; child_disaster integer; occupied bigint; max_capacity integer; camp_status text;
BEGIN
 CASE TG_TABLE_NAME
 WHEN 'victim_camp_assignment' THEN
   SELECT disaster_id INTO parent_disaster FROM victim WHERE victim_id=NEW.victim_id;
   SELECT disaster_id,capacity,status INTO child_disaster,max_capacity,camp_status FROM camp WHERE camp_id=NEW.camp_id FOR UPDATE;
   IF NEW.status='Active' THEN
     SELECT COUNT(*) INTO occupied FROM victim_camp_assignment WHERE camp_id=NEW.camp_id AND status='Active' AND assignment_id IS DISTINCT FROM NEW.assignment_id;
     IF camp_status<>'Open' OR occupied>=max_capacity THEN RAISE EXCEPTION 'Camp is closed or full' USING ERRCODE='23514'; END IF;
   END IF;
 WHEN 'volunteer_camp_assignment' THEN
   SELECT disaster_id INTO parent_disaster FROM volunteer_assignment WHERE assignment_id=NEW.assignment_id;
   SELECT disaster_id INTO child_disaster FROM camp WHERE camp_id=NEW.camp_id;
 WHEN 'vehicle_camp_allocation' THEN
   SELECT disaster_id INTO parent_disaster FROM vehicle_allocation WHERE allocation_id=NEW.allocation_id;
   SELECT disaster_id INTO child_disaster FROM camp WHERE camp_id=NEW.camp_id;
 WHEN 'camp_alert' THEN
   SELECT disaster_id INTO parent_disaster FROM alert WHERE alert_id=NEW.alert_id;
   SELECT disaster_id INTO child_disaster FROM camp WHERE camp_id=NEW.camp_id;
 WHEN 'distribution_source','camp_distribution' THEN
   SELECT disaster_id INTO parent_disaster FROM distribution WHERE distribution_id=NEW.distribution_id FOR UPDATE;
   SELECT disaster_id INTO child_disaster FROM camp WHERE camp_id=NEW.camp_id;
 WHEN 'victim_distribution' THEN
   SELECT disaster_id INTO parent_disaster FROM distribution WHERE distribution_id=NEW.distribution_id FOR UPDATE;
   SELECT disaster_id INTO child_disaster FROM victim WHERE victim_id=NEW.victim_id;
 WHEN 'missing_report' THEN
   parent_disaster:=NEW.disaster_id;
   IF NEW.matched_victim_id IS NOT NULL THEN SELECT disaster_id INTO child_disaster FROM victim WHERE victim_id=NEW.matched_victim_id; END IF;
 WHEN 'medical_case' THEN
   IF NEW.assigned_medical_user_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM user_account WHERE user_id=NEW.assigned_medical_user_id AND role IN ('admin','medical') AND status='Active') THEN RAISE EXCEPTION 'Assigned account must be an active medical officer or administrator' USING ERRCODE='23514'; END IF;
 END CASE;
 IF parent_disaster IS NOT NULL AND child_disaster IS NOT NULL AND parent_disaster<>child_disaster THEN RAISE EXCEPTION 'Records must belong to the same disaster' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['victim_camp_assignment','volunteer_camp_assignment','vehicle_camp_allocation','camp_alert','distribution_source','camp_distribution','victim_distribution','missing_report','medical_case'] LOOP
   IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='relationship_guard' AND tgrelid=t::regclass) THEN
     EXECUTE format('CREATE TRIGGER relationship_guard BEFORE INSERT OR UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION relief360_relationship_guard()',t);
   END IF;
 END LOOP;
END $$;

CREATE OR REPLACE FUNCTION relief360_parent_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_TABLE_NAME='camp' THEN
   IF NEW.disaster_id<>OLD.disaster_id THEN RAISE EXCEPTION 'Camp disaster cannot be changed' USING ERRCODE='23514'; END IF;
   IF NEW.status='Closed' AND EXISTS(SELECT 1 FROM victim_camp_assignment WHERE camp_id=NEW.camp_id AND status='Active') THEN RAISE EXCEPTION 'Release or transfer residents before closing the camp' USING ERRCODE='23514'; END IF;
   IF NEW.capacity<(SELECT COUNT(*) FROM victim_camp_assignment WHERE camp_id=NEW.camp_id AND status='Active') THEN RAISE EXCEPTION 'Capacity cannot be lower than current occupancy' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='user_account' THEN
   IF (NEW.role NOT IN ('admin','medical') OR NEW.status<>'Active') AND EXISTS(SELECT 1 FROM medical_case WHERE assigned_medical_user_id=NEW.user_id AND status<>'Closed') THEN RAISE EXCEPTION 'Reassign open medical cases before changing account role/status' USING ERRCODE='23514'; END IF;
 ELSIF NEW.disaster_id<>OLD.disaster_id THEN RAISE EXCEPTION 'Disaster identity of an existing record cannot be changed' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['camp','victim','volunteer_assignment','vehicle_allocation','distribution','alert','missing_report','user_account'] LOOP
   IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='parent_guard' AND tgrelid=t::regclass) THEN
     EXECUTE format('CREATE TRIGGER parent_guard BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION relief360_parent_guard()',t);
   END IF;
 END LOOP;
END $$;

-- Check complete distributions at COMMIT, after all child rows have been inserted.
CREATE OR REPLACE FUNCTION relief360_complete_distribution() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE current_id integer; previous_id integer; transaction_id integer; target_count bigint;
BEGIN
 IF TG_OP<>'DELETE' THEN current_id:=NEW.distribution_id; END IF;
 IF TG_OP<>'INSERT' THEN previous_id:=OLD.distribution_id; END IF;
 FOREACH transaction_id IN ARRAY ARRAY[current_id,previous_id] LOOP
   IF transaction_id IS NOT NULL AND EXISTS(SELECT 1 FROM distribution WHERE distribution_id=transaction_id) THEN
     PERFORM 1 FROM distribution WHERE distribution_id=transaction_id FOR UPDATE;
     SELECT (SELECT COUNT(*) FROM camp_distribution WHERE distribution_id=transaction_id)+(SELECT COUNT(*) FROM victim_distribution WHERE distribution_id=transaction_id) INTO target_count;
     IF target_count<>1 OR (SELECT COUNT(*) FROM distribution_source WHERE distribution_id=transaction_id)<>1 OR NOT EXISTS(SELECT 1 FROM distribution_item WHERE distribution_id=transaction_id) THEN
       RAISE EXCEPTION 'Distribution requires one source, exactly one recipient, and at least one item' USING ERRCODE='23514';
     END IF;
   END IF;
 END LOOP;
 RETURN NULL;
END $$;
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['distribution','distribution_source','camp_distribution','victim_distribution','distribution_item'] LOOP
   IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='complete_distribution' AND tgrelid=t::regclass) THEN
     EXECUTE format('CREATE CONSTRAINT TRIGGER complete_distribution AFTER INSERT OR UPDATE OR DELETE ON %I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION relief360_complete_distribution()',t);
   END IF;
 END LOOP;
END $$;
